import { test } from 'node:test';
import * as assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

/**
 * Acceptance test for Linux socket territory observation.
 * Target implementation must export 'observeLinuxSocketTerritory'.
 */
import * as target from './linux-socket-territory-observation-capcell-fabrication.mjs';

test('exact-loopback-tcp-territory', async () => {
    const tmp = mkdtempSync(join(tmpdir(), 'sock-obs-'));
    try {
        assert.ok(typeof target.observeLinuxSocketTerritory === 'function', 'API export missing');

        const admissibility = { denominator: "65535" };
        const snapshot = {
            namespace: "default",
            family: "inet",
            protocol: "tcp",
            sockets: [{ local: "127.0.0.1", port: "8080", state: "LISTEN" }]
        };

        const result = target.observeLinuxSocketTerritory(snapshot, admissibility);

        // Verification of typed quantities
        assert.strictEqual(typeof result.capacity, 'object');
        assert.strictEqual(typeof result.occupancy, 'object');

        // Assert reduced exact fractions
        assert.strictEqual(result.occupancy.fraction, "1/65535");
        assert.strictEqual(result.capacity.fraction, "65535/65535");

        // Assert absence of forbidden types
        assert.ok(!JSON.stringify(result).includes('.'), 'Floating point detected');
        assert.ok(!result.price, 'Price claim leaked');
        assert.ok(!result.socket, 'Socket handle leaked');

    } finally {
        rmSync(tmp, { recursive: true });
    }
});

test('typed-observation-refusal', async () => {
    const tmp = mkdtempSync(join(tmpdir(), 'sock-obs-'));
    try {
        // Given an unobservable kernel state
        const invalidSnapshot = null;
        const result = target.observeLinuxSocketTerritory(invalidSnapshot, { denominator: "1" });

        // Assert refusal is typed and contains evidence
        assert.strictEqual(result.status, 'refused');
        assert.strictEqual(typeof result.reason, 'string');
        assert.ok(result.reason.length > 0, 'Refusal must be descriptive');

        // Assert no zero-fabrication
        assert.strictEqual(result.capacity, undefined, 'Should not fabricate zero capacity');

    } finally {
        rmSync(tmp, { recursive: true });
    }
});
